const fs = require('fs');

const sourcePath = '/home/node/.n8n-files/to_analyze.txt';
const lastReportPath = '/home/node/.n8n-files/last_report.txt';
const archiveDir = '/home/node/.n8n-files/archive';

// Utwórz archiwum jeśli nie istnieje
if (!fs.existsSync(archiveDir)) {
    fs.mkdirSync(archiveDir, { recursive: true });
}

// Pobierz wynik Gemini z odpowiedzi Telegrama (result.text = tekst wysłanej wiadomości)
const raw = $input.first().json;
const geminiResult = 
    raw?.result?.text ||
    raw?.content?.parts?.[0]?.text ||
    raw?.text ||
    '';

// Zapisz ostatni raport Gemini (dashboard będzie to czytał)
const report = {
    timestamp: new Date().toISOString(),
    analysis: geminiResult
};
fs.writeFileSync(lastReportPath, JSON.stringify(report, null, 2));

// Archiwizuj oryginalny plik zamiast usuwać
if (fs.existsSync(sourcePath)) {
    const ts = new Date().toISOString().replace(/[:.]/g, '-');
    fs.renameSync(sourcePath, `${archiveDir}/to_analyze_${ts}.txt`);
}

return $input.all();

const fs = require('fs');
const path = require('path');

// ── 1. DANE Z last_report.txt ─────────────────────────────────────────────────
const inputData = $input.first().json;
let analysis = "";
let timestamp = "brak danych";
let isStale = false;

try {
    const raw = inputData?.data || (typeof inputData === 'string' ? inputData : JSON.stringify(inputData));
    const report = JSON.parse(raw);
    analysis = report.analysis || "";
    timestamp = report.timestamp || "brak danych";
    if (timestamp !== "brak danych") {
        const ageMinutes = (Date.now() - new Date(timestamp).getTime()) / 60000;
        isStale = ageMinutes > 10;
    }
} catch (e) {
    analysis = inputData?.data || JSON.stringify(inputData, null, 2);
}

if (!analysis || analysis.trim() === "") {
    analysis = "⏳ Brak danych — czekam na pierwszą analizę Gemini...";
}

// ── 2. HISTORIA Z ARCHIWUM ────────────────────────────────────────────────────
const archiveDir = '/home/node/data/archive';
let historyRows = '';
let chartLabels = [];
let chartScores = [];
let totalAnalyses = 0;
let avgScore = 0;
let minScore = 100;
let maxScore = 0;

try {
    if (fs.existsSync(archiveDir)) {
        const files = fs.readdirSync(archiveDir)
            .filter(f => f.endsWith('.txt'))
            .sort()
            .slice(-10); // ostatnie 10

        totalAnalyses = files.length;
        let scoreSum = 0;
        let scoreCount = 0;

        files.forEach((file, idx) => {
            try {
                const content = fs.readFileSync(path.join(archiveDir, file), 'utf8');

                // Wyciągnij timestamp z nazwy pliku: to_analyze_2026-02-27T13-48-16-320Z.txt
                const tsMatch = file.match(/to_analyze_(.+)\.txt/);
                const fileTs = tsMatch ? tsMatch[1].replace(/T(\d{2})-(\d{2})-(\d{2})-(\d{3})Z/, 'T$1:$2:$3.$4Z') : '';
                let displayTime = fileTs ? new Date(fileTs).toLocaleString('pl-PL', {timeZone:'Europe/Warsaw'}) : file;

                // Wyciągnij Health Score z pliku
                const scoreMatch = content.match(/Health Score:\s*([\d.]+)%/) || content.match(/([\d.]+)%/);
                const score = scoreMatch ? parseFloat(scoreMatch[1]) : null;
                const errorMatch = content.match(/Error Rate:\s*([\d.]+)%/);
                const errorRate = errorMatch ? errorMatch[1] : '—';
                const eventsMatch = content.match(/Total events analyzed:\s*(\d+)/);
                const events = eventsMatch ? eventsMatch[1] : '—';

                if (score !== null) {
                    scoreSum += score;
                    scoreCount++;
                    if (score < minScore) minScore = score;
                    if (score > maxScore) maxScore = score;
                    chartLabels.push(displayTime.split(',')[0]); // tylko data
                    chartScores.push(score);
                }

                const statusDot = score === null ? '⚪' : score >= 90 ? '🟢' : score >= 75 ? '🟡' : '🔴';
                const scoreDisplay = score !== null ? `${score.toFixed(1)}%` : '—';
                const rowClass = score !== null && score < 80 ? 'row-alert' : '';

                historyRows += `
                <tr class="${rowClass}">
                    <td class="ts-cell">${displayTime}</td>
                    <td>${statusDot} <span class="score-val">${scoreDisplay}</span></td>
                    <td class="text-muted">${errorRate}%</td>
                    <td class="text-muted">${events}</td>
                </tr>`;
            } catch(e2) {}
        });

        if (scoreCount > 0) avgScore = (scoreSum / scoreCount).toFixed(1);
        if (minScore === 100) minScore = 0;
    }
} catch(e) {}

// ── 3. PARSOWANIE BIEŻĄCEJ ANALIZY ───────────────────────────────────────────
const safeAnalysis = analysis
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const healthMatch = safeAnalysis.match(/([\d]+(?:\.[\d]+)?)%/) || safeAnalysis.match(/Health Score:?\s*([\d]+)/i);
const healthScore = healthMatch ? parseFloat(healthMatch[1]) : null;
const healthDisplay = healthScore !== null ? healthScore.toFixed(1) : '??';

const errorMatch = safeAnalysis.match(/Error Rate:?\s*([\d.]+)%/i);
const errorDisplay = errorMatch ? errorMatch[1] : '??';

const eventsMatch = safeAnalysis.match(/Total events analyzed:?\s*(\d+)/i);
const eventsDisplay = eventsMatch ? eventsMatch[1] : '??';

const errorsMatch = safeAnalysis.match(/Total errors detected:?\s*(\d+)/i);
const errorsDisplay = errorsMatch ? errorsMatch[1] : '??';

// Status systemu
let statusLabel, statusColor, statusGlow, gaugeColor;
if (healthScore === null) {
    statusLabel = 'UNKNOWN'; statusColor = '#64748b'; statusGlow = '#64748b'; gaugeColor = '#64748b';
} else if (healthScore >= 90) {
    statusLabel = 'HEALTHY'; statusColor = '#10b981'; statusGlow = '#10b981'; gaugeColor = '#10b981';
} else if (healthScore >= 75) {
    statusLabel = 'DEGRADED'; statusColor = '#f59e0b'; statusGlow = '#f59e0b'; gaugeColor = '#f59e0b';
} else {
    statusLabel = 'CRITICAL'; statusColor = '#ef4444'; statusGlow = '#ef4444'; gaugeColor = '#ef4444';
}

// Gauge SVG - arc od -135° do +135° (270° łuk)
const gaugeValue = healthScore !== null ? Math.min(Math.max(healthScore, 0), 100) : 0;
const gaugeAngle = (gaugeValue / 100) * 270 - 135;
const r = 54;
const cx = 70, cy = 70;
function polarToXY(deg, radius) {
    const rad = (deg - 90) * Math.PI / 180;
    return { x: cx + radius * Math.cos(rad), y: cy + radius * Math.sin(rad) };
}
const startPt = polarToXY(-135, r);
const endPt = polarToXY(gaugeAngle, r);
const largeArc = (gaugeAngle - (-135)) > 180 ? 1 : 0;
const gaugePath = `M ${startPt.x} ${startPt.y} A ${r} ${r} 0 ${largeArc} 1 ${endPt.x} ${endPt.y}`;
const bgEndPt = polarToXY(135, r);
const bgPath = `M ${startPt.x} ${startPt.y} A ${r} ${r} 0 1 1 ${bgEndPt.x} ${bgEndPt.y}`;

const formattedTimestamp = timestamp !== "brak danych"
    ? new Date(timestamp).toLocaleString('pl-PL', { timeZone: 'Europe/Warsaw' })
    : "brak danych";

const refreshInterval = 60;
const chartLabelsJSON = JSON.stringify(chartLabels);
const chartScoresJSON = JSON.stringify(chartScores);

// ── 4. HTML ───────────────────────────────────────────────────────────────────
const html = `<!DOCTYPE html>
<html lang="pl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>SRE Operations Center</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;600;700&family=Syne:wght@400;600;800&display=swap" rel="stylesheet">
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
:root {
    --bg: #060b14;
    --surface: #0d1626;
    --surface2: #111d33;
    --border: #1e3a5f;
    --text: #cdd9f0;
    --muted: #4a6494;
    --accent: #38bdf8;
    --status: ${statusColor};
    --glow: ${statusGlow};
    --mono: 'JetBrains Mono', monospace;
    --sans: 'Syne', sans-serif;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
    background: var(--bg);
    color: var(--text);
    font-family: var(--mono);
    min-height: 100vh;
    background-image: 
        radial-gradient(ellipse 80% 50% at 50% -20%, #0e2a4a44, transparent),
        repeating-linear-gradient(0deg, transparent, transparent 39px, #1e3a5f11 39px, #1e3a5f11 40px),
        repeating-linear-gradient(90deg, transparent, transparent 39px, #1e3a5f11 39px, #1e3a5f11 40px);
}

/* TOPBAR */
.topbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 32px;
    background: rgba(13,22,38,0.95);
    border-bottom: 1px solid var(--border);
    backdrop-filter: blur(10px);
    position: sticky;
    top: 0;
    z-index: 100;
}
.topbar-brand {
    font-family: var(--sans);
    font-weight: 800;
    font-size: 1.1rem;
    letter-spacing: 0.05em;
    color: var(--accent);
    display: flex;
    align-items: center;
    gap: 10px;
}
.topbar-brand::before {
    content: '';
    width: 8px; height: 8px;
    border-radius: 50%;
    background: var(--status);
    box-shadow: 0 0 8px var(--glow);
    animation: pulse 2s infinite;
}
@keyframes pulse {
    0%, 100% { opacity: 1; transform: scale(1); }
    50% { opacity: 0.5; transform: scale(0.85); }
}
.topbar-meta {
    display: flex;
    gap: 24px;
    align-items: center;
    font-size: 0.72rem;
    color: var(--muted);
}
.topbar-meta span { display: flex; align-items: center; gap: 6px; }
.status-badge {
    font-family: var(--sans);
    font-weight: 600;
    font-size: 0.78rem;
    letter-spacing: 0.12em;
    padding: 4px 14px;
    border-radius: 2px;
    border: 1px solid var(--status);
    color: var(--status);
    box-shadow: 0 0 12px ${statusGlow}44;
}

/* REFRESH BAR */
.refresh-bar { height: 2px; background: var(--surface2); }
.refresh-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--accent), #818cf8);
    transition: width 1s linear;
}

/* LAYOUT */
.main { padding: 24px 32px; max-width: 1400px; margin: 0 auto; }

/* KPI ROW */
.kpi-row {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 24px;
}
.kpi-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 4px;
    padding: 18px 20px;
    position: relative;
    overflow: hidden;
}
.kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: var(--accent);
}
.kpi-card.alert::before { background: #ef4444; }
.kpi-card.warn::before { background: #f59e0b; }
.kpi-label {
    font-size: 0.65rem;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: var(--muted);
    margin-bottom: 8px;
}
.kpi-value {
    font-family: var(--sans);
    font-weight: 800;
    font-size: 2rem;
    line-height: 1;
    color: var(--text);
}
.kpi-value.status-color { color: var(--status); }
.kpi-sub { font-size: 0.7rem; color: var(--muted); margin-top: 4px; }

/* MIDDLE GRID */
.mid-grid {
    display: grid;
    grid-template-columns: 160px 1fr;
    gap: 16px;
    margin-bottom: 24px;
    align-items: start;
}

/* GAUGE */
.gauge-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 4px;
    padding: 20px 16px;
    text-align: center;
}
.gauge-card svg { overflow: visible; }
.gauge-label {
    font-size: 0.62rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--muted);
    margin-top: 8px;
}

/* CHART */
.chart-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 4px;
    padding: 20px;
}
.card-title {
    font-size: 0.65rem;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: var(--muted);
    margin-bottom: 14px;
}
.chart-wrap { height: 120px; }

/* BOTTOM GRID */
.bottom-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
}

/* TERMINAL */
.terminal-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 4px;
    overflow: hidden;
}
.terminal-header {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 10px 16px;
    background: var(--surface2);
    border-bottom: 1px solid var(--border);
}
.dot { width: 10px; height: 10px; border-radius: 50%; }
.terminal-title { font-size: 0.65rem; letter-spacing: 0.15em; text-transform: uppercase; color: var(--muted); margin-left: 4px; }
.terminal-body {
    padding: 16px;
    font-size: 0.75rem;
    line-height: 1.7;
    color: #10b981;
    white-space: pre-wrap;
    overflow-y: auto;
    max-height: 360px;
    background: #020810;
}
.terminal-body::-webkit-scrollbar { width: 4px; }
.terminal-body::-webkit-scrollbar-track { background: transparent; }
.terminal-body::-webkit-scrollbar-thumb { background: var(--border); border-radius: 2px; }

/* HISTORY TABLE */
.history-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 4px;
    overflow: hidden;
}
.history-header {
    padding: 12px 16px;
    background: var(--surface2);
    border-bottom: 1px solid var(--border);
    display: flex;
    justify-content: space-between;
    align-items: center;
}
.history-count {
    font-size: 0.65rem;
    color: var(--muted);
}
table { width: 100%; border-collapse: collapse; }
th {
    font-size: 0.6rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--muted);
    padding: 8px 12px;
    text-align: left;
    border-bottom: 1px solid var(--border);
    font-weight: 400;
}
td {
    font-size: 0.72rem;
    padding: 9px 12px;
    border-bottom: 1px solid #1e3a5f44;
    color: var(--text);
}
tr.row-alert td { background: #ef444408; }
tr:last-child td { border-bottom: none; }
.ts-cell { color: var(--muted); font-size: 0.67rem; }
.score-val { font-weight: 600; }

/* STALE WARNING */
.stale-bar {
    background: #7c3aed22;
    border-left: 3px solid #7c3aed;
    padding: 8px 16px;
    font-size: 0.72rem;
    color: #c4b5fd;
    margin-bottom: 16px;
}

@media (max-width: 900px) {
    .kpi-row { grid-template-columns: repeat(2,1fr); }
    .mid-grid { grid-template-columns: 1fr; }
    .bottom-grid { grid-template-columns: 1fr; }
    .main { padding: 16px; }
}
</style>
</head>
<body>

<!-- TOPBAR -->
<div class="topbar">
    <div class="topbar-brand">SRE OPERATIONS CENTER</div>
    <div class="topbar-meta">
        <span>📅 ${formattedTimestamp}</span>
        <span>🔄 odświeżenie za <strong id="cdown" style="color:var(--accent)">${refreshInterval}</strong>s</span>
        <div class="status-badge">${statusLabel}</div>
    </div>
</div>
<div class="refresh-bar"><div class="refresh-fill" id="rfill" style="width:100%"></div></div>

<div class="main">

    ${isStale ? `<div class="stale-bar">⚠ Dane nieaktualne — ostatnia analiza: ${formattedTimestamp}</div>` : ''}

    <!-- KPI ROW -->
    <div class="kpi-row">
        <div class="kpi-card">
            <div class="kpi-label">Health Score</div>
            <div class="kpi-value status-color">${healthDisplay}${healthScore !== null ? '%' : ''}</div>
            <div class="kpi-sub">aktualny cykl</div>
        </div>
        <div class="kpi-card ${parseFloat(errorDisplay) > 15 ? 'alert' : parseFloat(errorDisplay) > 8 ? 'warn' : ''}">
            <div class="kpi-label">Error Rate</div>
            <div class="kpi-value">${errorDisplay}${errorDisplay !== '??' ? '%' : ''}</div>
            <div class="kpi-sub">bieżący raport</div>
        </div>
        <div class="kpi-card">
            <div class="kpi-label">Events Analyzed</div>
            <div class="kpi-value">${eventsDisplay}</div>
            <div class="kpi-sub">w ostatnim cyklu</div>
        </div>
        <div class="kpi-card">
            <div class="kpi-label">Avg Health (hist.)</div>
            <div class="kpi-value">${avgScore || '—'}${avgScore ? '%' : ''}</div>
            <div class="kpi-sub">ostatnie ${totalAnalyses} analiz</div>
        </div>
    </div>

    <!-- GAUGE + CHART -->
    <div class="mid-grid">
        <div class="gauge-card">
            <svg width="140" height="100" viewBox="0 0 140 100">
                <defs>
                    <filter id="glow">
                        <feGaussianBlur stdDeviation="3" result="coloredBlur"/>
                        <feMerge><feMergeNode in="coloredBlur"/><feMergeNode in="SourceGraphic"/></feMerge>
                    </filter>
                </defs>
                <!-- BG arc -->
                <path d="${bgPath}" fill="none" stroke="#1e3a5f" stroke-width="10" stroke-linecap="round"/>
                <!-- Value arc -->
                <path d="${gaugePath}" fill="none" stroke="${gaugeColor}" stroke-width="10" stroke-linecap="round" filter="url(#glow)"/>
                <!-- Center value -->
                <text x="70" y="66" text-anchor="middle" font-family="Syne,sans-serif" font-weight="800" font-size="22" fill="${gaugeColor}">${healthDisplay}</text>
                <text x="70" y="80" text-anchor="middle" font-family="JetBrains Mono,monospace" font-size="9" fill="#4a6494">HEALTH %</text>
            </svg>
            <div class="gauge-label">System Status</div>
        </div>

        <div class="chart-card">
            <div class="card-title">Health Score — historia analiz</div>
            <div class="chart-wrap">
                <canvas id="trendChart"></canvas>
            </div>
        </div>
    </div>

    <!-- TERMINAL + HISTORY -->
    <div class="bottom-grid">

        <div class="terminal-card">
            <div class="terminal-header">
                <div class="dot" style="background:#ef4444"></div>
                <div class="dot" style="background:#f59e0b"></div>
                <div class="dot" style="background:#10b981"></div>
                <span class="terminal-title">Gemini SRE Analysis</span>
            </div>
            <div class="terminal-body">${safeAnalysis}</div>
        </div>

        <div class="history-card">
            <div class="history-header">
                <div class="card-title" style="margin:0">Archive Log</div>
                <div class="history-count">${totalAnalyses} rekordów</div>
            </div>
            ${historyRows ? `
            <table>
                <thead>
                    <tr>
                        <th>Timestamp</th>
                        <th>Health</th>
                        <th>Err Rate</th>
                        <th>Events</th>
                    </tr>
                </thead>
                <tbody>${historyRows}</tbody>
            </table>` : `<div style="padding:24px;color:var(--muted);font-size:0.8rem;">Brak danych historycznych</div>`}
        </div>

    </div>
</div>

<script>
// Chart.js trend
const labels = ${chartLabelsJSON};
const scores = ${chartScoresJSON};

if (labels.length > 0) {
    const ctx = document.getElementById('trendChart').getContext('2d');
    new Chart(ctx, {
        type: 'line',
        data: {
            labels,
            datasets: [{
                data: scores,
                borderColor: '${statusColor}',
                backgroundColor: '${statusColor}22',
                borderWidth: 2,
                pointRadius: 3,
                pointBackgroundColor: '${statusColor}',
                fill: true,
                tension: 0.4
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: { legend: { display: false } },
            scales: {
                x: {
                    ticks: { color: '#4a6494', font: { size: 9, family: 'JetBrains Mono' }, maxRotation: 30 },
                    grid: { color: '#1e3a5f55' }
                },
                y: {
                    min: Math.max(0, Math.min(...scores) - 5),
                    max: 100,
                    ticks: { color: '#4a6494', font: { size: 9 }, callback: v => v + '%' },
                    grid: { color: '#1e3a5f55' }
                }
            }
        }
    });
}

// Auto-refresh countdown
let rem = ${refreshInterval};
const cdown = document.getElementById('cdown');
const rfill = document.getElementById('rfill');
setInterval(() => {
    rem--;
    cdown.textContent = rem;
    rfill.style.width = ((rem / ${refreshInterval}) * 100) + '%';
    if (rem <= 0) location.reload();
}, 1000);
</script>
</body>
</html>`;

return [{ json: { html } }];
